'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );


// VARIABLES //

var M = 3;


// MAIN //

/**
* Reverses a double-precision floating-point strided array in-place according to a mask.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Float64Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Uint8Array} mask - mask array
* @param {integer} strideMask - stride length for `mask`
* @param {NonNegativeInteger} offsetMask - starting index for `mask`
* @returns {Float64Array} input array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* var x = new Float64Array( [ -2.0, 1.0, 3.0, -5.0, 4.0, 0.0, -1.0, -3.0 ] );
* var mask = new Uint8Array( [ 0, 0, 0, 1, 0, 0, 0, 0 ] );
*
* dmskrev( x.length, x, 1, 0, mask, 1, 0 );
* // x => <Float64Array>[ -3.0, -1.0, 0.0, -5.0, 4.0, 3.0, 1.0, -2.0 ]
*/
function dmskrev( N, x, strideX, offsetX, mask, strideMask, offsetMask ) {
	var tmp;
	var ix;
	var iy;
	var im;
	var jm;
	var m;
	var n;
	var i;

	if ( N <= 0 ) {
		return x;
	}
	n = floor( N/2 );
	ix = offsetX;
	im = offsetMask;

	// Use loop unrolling if the strides are equal to `1`...
	if ( strideX === 1 && strideMask === 1 ) {
		m = n % M;
		iy = ix + N - 1;
		jm = im + N - 1;

		// If we have a remainder, run a clean-up loop...
		if ( m > 0 ) {
			for ( i = 0; i < m; i++ ) {
				if ( mask[ im ] === 0 && mask[ jm ] === 0 ) {
					tmp = x[ ix ];
					x[ ix ] = x[ iy ];
					x[ iy ] = tmp;
				}
				ix += 1;
				im += 1;
				iy -= 1;
				jm -= 1;
			}
		}
		if ( n < M ) {
			return x;
		}
		for ( i = m; i < n; i += M ) {
			if ( mask[ im ] === 0 && mask[ jm ] === 0 ) {
				tmp = x[ ix ];
				x[ ix ] = x[ iy ];
				x[ iy ] = tmp;
			}
			if ( mask[ im+1 ] === 0 && mask[ jm-1 ] === 0 ) {
				tmp = x[ ix+1 ];
				x[ ix+1 ] = x[ iy-1 ];
				x[ iy-1 ] = tmp;
			}
			if ( mask[ im+2 ] === 0 && mask[ jm-2 ] === 0 ) {
				tmp = x[ ix+2 ];
				x[ ix+2 ] = x[ iy-2 ];
				x[ iy-2 ] = tmp;
			}
			ix += M;
			im += M;
			iy -= M;
			jm -= M;
		}
		return x;
	}
	iy = ix + ( (N-1) * strideX );
	jm = im + ( (N-1) * strideMask );
	for ( i = 0; i < n; i++ ) {
		if ( mask[ im ] === 0 && mask[ jm ] === 0 ) {
			tmp = x[ ix ];
			x[ ix ] = x[ iy ];
			x[ iy ] = tmp;
		}
		ix += strideX;
		im += strideMask;
		iy -= strideX;
		jm -= strideMask;
	}
	return x;
}


// EXPORTS //

module.exports = dmskrev;
